#' Load the bundled example data
#'
#' A small synthetic dataset (one 60 kb chromosome, five genes, binding peaks
#' in two conditions, a mappability track with one low-mappability region,
#' and two differential expression tables) used in examples, tests and the
#' vignette. Generated by `inst/scripts/make_example_data.R`.
#'
#' @return A list with `peaks` (`GRanges`), `genes` (`locusGeneModels`),
#'   `groups` (from [defineGroups()]), `signal` (named list of bigWig sources
#'   `A` and `B`), `mappability` (bigWig source) and `expression` (long
#'   `data.frame` for expression insets).
#' @examples
#' ex <- locusPickExample()
#' names(ex)
#' @export
locusPickExample <- function() {
    f <- function(x) system.file("extdata", x, package = "LocusPick", mustWork = TRUE)
    de <- utils::read.delim(f("toy_de.tsv"), stringsAsFactors = FALSE)
    groups <- defineGroups(
        deTable(de, gene = "gene", lfc = "ko_lfc", padj = "ko_padj"),
        deTable(de, gene = "gene", lfc = "cond_lfc", padj = "cond_padj"),
        conditionName = "condition")
    list(peaks = asPeaks(f("toy_peaks.bed")),
         genes = readGeneModels(f("toy.gtf")),
         groups = groups,
         signal = list(A = bigWigSource(f("toy_A.bw")), B = bigWigSource(f("toy_B.bw"))),
         mappability = bigWigSource(f("toy_map.bw")),
         expression = utils::read.delim(f("toy_expression.tsv"), stringsAsFactors = FALSE))
}
